<?php

namespace App\Entity;

use ApiPlatform\Metadata\ApiProperty;
use ApiPlatform\Metadata\ApiResource;
use ApiPlatform\Metadata\Get;
use ApiPlatform\Metadata\GetCollection;
use ApiPlatform\Metadata\HeaderParameter;
use Doctrine\Common\Collections\Criteria;
use Doctrine\Common\Collections\Collection;
use Doctrine\ORM\Mapping as ORM;
use ApiPlatform\Metadata\QueryParameter;

#[ORM\Entity]
#[ORM\Table(name: 'author')]
#[ApiResource(
    shortName: 'authors',
    operations: [
        new GetCollection(
            uriTemplate: '/authors',
            parameters: [
                'include' => new QueryParameter(description: 'Related resources to include: books'),
            ],
        ),
        new Get(
            uriTemplate: '/authors/{id}',
            parameters: [
                'include' => new QueryParameter(description: 'Related resources to include: books'),
            ],
        ),
    ],
)]
class Author
{
    #[ORM\Id]
    #[ORM\GeneratedValue]
    #[ORM\Column(name: 'id', type: 'integer')]
    private ?int $id = null;

    #[ORM\Column(name: 'name', type: 'text', nullable: true)]
    private ?string $name = null;

    /** @var Collection<int, Book> */
    #[ORM\OneToMany(targetEntity: Book::class, mappedBy: 'author')]
    #[ORM\OrderBy(['id' => 'ASC'])]
    #[ApiProperty(readable: false, writable: false)]
    private Collection $allBooks;

    public function __construct()
    {
        $this->allBooks = new \Doctrine\Common\Collections\ArrayCollection();
    }

    public function getId(): ?int
    {
        return $this->id;
    }

    public function getName(): ?string
    {
        return $this->name;
    }

    /**
     * Published books only, in id order.
     *
     * @return Collection<int, Book>
     */
    public function getBooks(): Collection
    {
        return $this->allBooks->matching(
            Criteria::create()
                ->where(Criteria::expr()->eq('published', true))
                ->orderBy(['id' => Criteria::ASC]),
        );
    }

    public function getPublishedBooks(): int
    {
        return $this->getBooks()->count();
    }
}
EOF
