    $data = [
        'book' => $pdo->query('select id, title, price_cents, stock from book order by id')->fetchAll(PDO::FETCH_ASSOC),
        'purchase_max' => $pdo->query('select coalesce(max(id),0) from purchase')->fetchColumn(),
        'purchase_line_max' => $pdo->query('select coalesce(max(id),0) from purchase_line')->fetchColumn(),
    ];
    file_put_contents($file, json_encode($data));
    echo "saved ", count($data['book']), " books\n";
} else {
    $data = json_decode(file_get_contents($file), true);
    $pdo->beginTransaction();
    foreach ($data['book'] as $b) {
        $pdo->prepare('update book set title=?, price_cents=?, stock=? where id=?')->execute([$b['title'], $b['price_cents'], $b['stock'], $b['id']]);
    }
    $pdo->exec("delete from purchase_line where id > {$data['purchase_line_max']}");
    $pdo->exec("delete from purchase where id > {$data['purchase_max']}");
    $pdo->commit();
    echo "restored\n";
}
